import contextlib
import io
import unittest

from solution import build_progression_lines


class BuildProgressionLinesTests(unittest.TestCase):
    def test_positive_and_negative_seeds(self):
        self.assertEqual(
            build_progression_lines(4, 3),
            ("4 + 0 = 4", "4 + 1 = 5", "4 + 2 = 6", "4 + 3 = 7"),
        )
        self.assertEqual(
            build_progression_lines(-2, 3),
            ("-2 + 0 = -2", "-2 + 1 = -1", "-2 + 2 = 0", "-2 + 3 = 1"),
        )

    def test_zero_limit_is_inclusive_and_returns_tuple(self):
        result = build_progression_lines(10, 0)
        self.assertEqual(result, ("10 + 0 = 10",))
        self.assertIsInstance(result, tuple)

    def test_large_integer_decimal_representation(self):
        seed = 10 ** 30
        self.assertEqual(build_progression_lines(seed, 1), (
            "1000000000000000000000000000000 + 0 = 1000000000000000000000000000000",
            "1000000000000000000000000000000 + 1 = 1000000000000000000000000000001",
        ))

    def test_performs_no_printing(self):
        stream = io.StringIO()
        with contextlib.redirect_stdout(stream):
            build_progression_lines(1, 2)
        self.assertEqual(stream.getvalue(), "")

    def test_invalid_types(self):
        for seed in (True, False, 1.0, "1", None):
            with self.subTest(seed=seed):
                with self.assertRaises(TypeError):
                    build_progression_lines(seed, 1)
        for limit in (True, False, 1.0, "1", None):
            with self.subTest(limit=limit):
                with self.assertRaises(TypeError):
                    build_progression_lines(1, limit)

    def test_negative_limit(self):
        with self.assertRaises(ValueError):
            build_progression_lines(1, -1)


if __name__ == "__main__":
    unittest.main()

